function update(){g.setAttribute('transform',`translate(${tx},${ty}) scale(${scale})`)}svg.onwheel=e=>{e.preventDefault();scale*=e.deltaY<0?1.12:.89;update()};let drag;svg.onpointerdown=e=>{drag=[e.clientX,e.clientY,tx,ty];svg.setPointerCapture(e.pointerId)};svg.onpointermove=e=>{if(moving){const p=new DOMPoint(e.clientX,e.clientY).matrixTransform(g.getScreenCTM().inverse());moving.x=p.x;moving.y=p.y;return}if(drag){tx=drag[2]+(e.clientX-drag[0])*1200/svg.clientWidth;ty=drag[3]+(e.clientY-drag[1])*900/svg.clientHeight;update()}};svg.onpointerup=()=>{drag=null;moving=null};svg.onpointercancel=()=>{drag=null;moving=null};detail.textContent+='\n\n'+types.map((t,i)=>t+' '+colors[i]).join('\n');let tick=0;function animate(){if(!paused){const ns=data.nodes;for(let i=0;i<ns.length;i++){let a=ns[i];if(a===moving)continue;let fx=-a.x*.0006,fy=-a.y*.0006;for(let j=0;j<ns.length;j++){if(i===j)continue;let b=ns[j],dx=a.x-b.x,dy=a.y-b.y,d=Math.max(20,Math.hypot(dx,dy));fx+=dx/d*900/(d*d);fy+=dy/d*900/(d*d)}for(const e of data.edges){if(e.source!==a.id&&e.target!==a.id)continue;let b=ns.find(n=>n.id===(e.source===a.id?e.target:e.source));if(!b)continue;let dx=b.x-a.x,dy=b.y-a.y,d=Math.max(1,Math.hypot(dx,dy));fx+=dx/d*(d-110)*.001;fy+=dy/d*(d-110)*.001}a.x+=Math.max(-3,Math.min(3,fx));a.y+=Math.max(-3,Math.min(3,fy))}}const m=new Map(data.nodes.map(n=>[n.id,n]));data.nodes.forEach(n=>{n.c.setAttribute('cx',n.x);n.c.setAttribute('cy',n.y);n.t.setAttribute('x',n.x+8);n.t.setAttribute('y',n.y)});data.edges.forEach(e=>{const a=m.get(e.source),b=m.get(e.target);e.line.setAttribute('x1',a.x);e.line.setAttribute('y1',a.y);e.line.setAttribute('x2',b.x);e.line.setAttribute('y2',b.y)});requestAnimationFrame(animate)}animate();